INSERT INTO PRODUCT_FAQS (faq_id, question, answer, product_id) VALUES
(1, 'Bể tiểu cảnh kín này cần tưới nước bao lâu một lần?', 'Bạn chỉ cần tưới phun sương nhẹ khoảng 2-4 tuần một lần khi thấy rêu hơi nhạt màu hoặc thành bình không còn đọng sương.', 16),
(2, 'Tôi nên đặt bể tiểu cảnh ở đâu trong phòng?', 'Hãy đặt bể ở nơi có ánh sáng gián tiếp mát mẻ như bàn làm việc, kệ sách hoặc gần cửa sổ. Tránh ánh nắng mặt trời chiếu trực tiếp vì sẽ làm nóng bên trong bể và làm chết cây/rêu.', 16),
(3, 'Bể tiểu cảnh kín này cần tưới nước bao lâu một lần?', 'Bạn chỉ cần tưới phun sương nhẹ khoảng 2-4 tuần một lần khi thấy rêu hơi nhạt màu hoặc thành bình không còn đọng sương.', 17),
